/**
 * Build a search entry for every substring of a municipality to allow for matching on parts of words.
 * so Acton => acton, cton, ton, on
 *
 * @param d
 * @returns {*}
 */
let muniTokenizer = function(d) {
    let test = Bloodhound.tokenizers.whitespace(d.name);
    $.each(test,function(k,v){ i = 1; while( (i+1) <= v.length ){ test.push(v.substring(i,v.length)); i++; } })
    return test;
};

